CustomCSS:
/* Arctic Aurora — high-impact polar night + aurora glow.
   Follows BetterSEQTA+ variables: https://docs.betterseqta.org/theme-creation/ */

@import url("https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap");

/* --- Core variable overrides (dark): everything using var(--background-*) inherits --- */
html.dark {
  --background-primary: #0c1222;
  --background-secondary: #152238;
  --theme-primary: #0c1222;
  --theme-secondary: #152238;
  --text-primary: #e8eefc;
  --text-color: #e8eefc;
}

/* Transparency mode: keep readable tints when glass is on */
html.transparencyEffects.dark {
  --background-primary: rgba(12, 18, 34, 0.72);
  --background-secondary: rgba(21, 34, 56, 0.72);
  --theme-primary: rgba(12, 18, 34, 0.72);
  --theme-secondary: rgba(21, 34, 56, 0.72);
}

/* Local tokens (accent-agnostic surfaces) */
:root {
  --arctic-ink: #070b14;
  --arctic-panel: #121a2f;
  --arctic-border: rgba(148, 163, 184, 0.22);
  --arctic-muted: #94a3b8;
}

@keyframes arctic-aurora-drift {
  0% {
    opacity: 0.42;
    transform: translate(-4%, -2%) scale(1);
  }
  50% {
    opacity: 0.72;
    transform: translate(3%, 2%) scale(1.03);
  }
  100% {
    opacity: 0.42;
    transform: translate(-4%, -2%) scale(1);
  }
}

@keyframes arctic-shimmer {
  0% {
    background-position: 0% 50%;
  }
  100% {
    background-position: 200% 50%;
  }
}

html.dark body {
  font-family: "Plus Jakarta Sans", system-ui, sans-serif !important;
}

/* Atmospheric shell */
#container {
  position: relative;
  isolation: isolate;
  background:
      radial-gradient(ellipse 130% 90% at 50% -25%, color-mix(in srgb, var(--better-main) 28%, transparent), transparent 58%),
      radial-gradient(ellipse 70% 55% at 100% 30%, rgba(167, 139, 250, 0.22), transparent 52%),
      radial-gradient(ellipse 55% 45% at 0% 85%, color-mix(in srgb, var(--better-main) 18%, transparent), transparent 48%),
      linear-gradient(168deg, var(--arctic-ink) 0%, #0b1428 42%, #0e1a32 100%) !important;
}

#container::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 78% 12%, color-mix(in srgb, var(--better-main) 40%, transparent), transparent 42%),
    radial-gradient(circle at 14% 88%, rgba(167, 139, 250, 0.35), transparent 46%);
  animation: arctic-aurora-drift 22s ease-in-out infinite;
  mix-blend-mode: screen;
  opacity: 0.85;
}

/* Scan-soft shimmer band (subtle motion) */
#container::after {
  content: "";
  position: fixed;
  inset: -20%;
  z-index: 0;
  pointer-events: none;
  opacity: 0.09;
  background: linear-gradient(
    115deg,
    transparent 0%,
    color-mix(in srgb, var(--better-main) 55%, transparent) 35%,
    rgba(167, 139, 250, 0.45) 50%,
    color-mix(in srgb, var(--better-main) 55%, transparent) 65%,
    transparent 100%
  );
  background-size: 240% 240%;
  animation: arctic-shimmer 28s linear infinite;
}

#menu,
#main {
  position: relative;
  z-index: 1;
}

/* Preserve BetterSEQTA+ fixed #title bar (injected.scss: position:fixed; z-index:20) */
#title {
  z-index: 21 !important;
}

/* Title bar — one strip; extension owns #title::before (logo) */
#title {
  background: linear-gradient(
      180deg,
      color-mix(in srgb, var(--arctic-panel) 92%, transparent) 0%,
      color-mix(in srgb, var(--background-secondary) 88%, transparent) 100%
    ) !important;
  color: var(--text-primary) !important;
  border-bottom: 1px solid color-mix(in srgb, var(--better-main) 38%, transparent) !important;
  box-shadow:
    0 8px 28px rgba(0, 0, 0, 0.4),
    0 0 40px color-mix(in srgb, var(--better-main) 14%, transparent) !important;
  backdrop-filter: blur(14px);
}

#title * {
  color: var(--text-primary) !important;
}

/* Sidebar — stronger rail + selection */
#menu {
  background: linear-gradient(
      180deg,
      color-mix(in srgb, var(--background-secondary) 94%, black) 0%,
      color-mix(in srgb, var(--arctic-panel) 96%, transparent) 100%
    ) !important;
  border-right: 1px solid var(--arctic-border) !important;
  box-shadow:
    8px 0 40px rgba(0, 0, 0, 0.42),
    0 0 36px color-mix(in srgb, var(--better-main) 12%, transparent) !important;
  color: var(--text-primary) !important;
  backdrop-filter: blur(16px);
}

#menu li:hover,
#menu section:hover {
  background: color-mix(in srgb, var(--better-main) 16%, transparent) !important;
}

#menu li.active,
#menu section.active {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--better-main) 26%, transparent),
    color-mix(in srgb, var(--better-main) 8%, transparent)
  ) !important;
  box-shadow:
    inset 4px 0 0 var(--better-main),
    inset 0 0 36px color-mix(in srgb, var(--better-main) 14%, transparent) !important;
}

#menu * {
  color: var(--text-primary) !important;
}

#main {
  background: transparent !important;
  color: var(--text-primary) !important;
}

#main > .dashboard section,
.dashlet,
.notice,
.document {
  position: relative;
  overflow: hidden;
  background: linear-gradient(
      165deg,
      color-mix(in srgb, var(--arctic-panel) 92%, transparent) 0%,
      color-mix(in srgb, var(--background-secondary) 88%, transparent) 100%
    ) !important;
  border: 1px solid var(--arctic-border) !important;
  border-radius: 14px !important;
  box-shadow:
    0 16px 48px rgba(0, 0, 0, 0.42),
    0 0 0 1px color-mix(in srgb, var(--better-main) 12%, transparent) inset,
    0 0 32px color-mix(in srgb, var(--better-main) 10%, transparent) !important;
  color: var(--text-primary) !important;
  backdrop-filter: blur(12px);
}

#main > .dashboard section::before,
.dashlet::before,
.notice::before,
.document::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 5px;
  border-radius: 14px 0 0 14px;
  background: linear-gradient(180deg, var(--better-main), rgba(167, 139, 250, 0.95));
  box-shadow: 0 0 18px color-mix(in srgb, var(--better-main) 45%, transparent);
  pointer-events: none;
}

.dashlet *,
.notice *,
.document * {
  color: var(--text-primary) !important;
}

html.transparencyEffects #main > .dashboard section,
html.transparencyEffects .dashlet,
html.transparencyEffects .notice,
html.transparencyEffects .document {
  backdrop-filter: blur(24px) saturate(1.15);
}

.uiButton,
.addedButton,
[class*="uiButton"] {
  background: linear-gradient(
      180deg,
      color-mix(in srgb, var(--arctic-panel) 95%, transparent),
      color-mix(in srgb, var(--background-secondary) 90%, transparent)
    ) !important;
  border: 1px solid color-mix(in srgb, var(--better-main) 42%, var(--arctic-border)) !important;
  border-radius: 11px !important;
  color: var(--text-primary) !important;
  box-shadow: 0 0 22px color-mix(in srgb, var(--better-main) 12%, transparent);
  transition: box-shadow 0.2s ease, transform 0.2s ease, border-color 0.2s ease;
}

.uiButton:hover,
.addedButton:hover {
  border-color: color-mix(in srgb, var(--better-main) 65%, transparent) !important;
  box-shadow:
    0 0 28px color-mix(in srgb, var(--better-main) 35%, transparent),
    0 8px 24px rgba(0, 0, 0, 0.35) !important;
}

.uiButton:hover {
  transform: translateY(-1px);
}

/* addedButton sits in tight toolbars — no shift; normal weight; room for glyph */
.addedButton {
  font-weight: 400 !important;
  letter-spacing: normal !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  line-height: 1 !important;
  padding: 6px 10px !important;
}

.addedButton:hover {
  transform: none !important;
}

.addedButton svg {
  flex-shrink: 0 !important;
  overflow: visible !important;
  display: block !important;
}


.quickbar {
  background: color-mix(in srgb, var(--arctic-panel) 92%, transparent) !important;
  border: 1px solid var(--arctic-border) !important;
  color: var(--text-primary) !important;
  border-radius: 14px !important;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.38);
}

.day {
  background: color-mix(in srgb, var(--background-primary) 88%, transparent) !important;
  border: 1px solid var(--arctic-border) !important;
  border-radius: 14px !important;
  color: var(--text-primary) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.shortcut {
  background: linear-gradient(
      135deg,
      color-mix(in srgb, var(--arctic-panel) 94%, transparent),
      color-mix(in srgb, var(--background-secondary) 88%, transparent)
    ) !important;
  border: 1px solid color-mix(in srgb, var(--better-main) 25%, var(--arctic-border)) !important;
  border-radius: 14px !important;
  color: var(--text-primary) !important;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.shortcut:hover {
  box-shadow:
    0 0 32px color-mix(in srgb, var(--better-main) 38%, transparent),
    0 14px 36px rgba(0, 0, 0, 0.4) !important;
  transform: translateY(-2px);
}

input,
select,
textarea {
  background: color-mix(in srgb, var(--background-primary) 94%, transparent) !important;
  border: 1px solid var(--arctic-border) !important;
  border-radius: 11px !important;
  color: var(--text-primary) !important;
}

input::placeholder,
textarea::placeholder {
  color: var(--arctic-muted) !important;
}

a {
  color: var(--better-main) !important;
}

a:hover {
  color: color-mix(in srgb, var(--better-main) 82%, white) !important;
  text-shadow: 0 0 14px color-mix(in srgb, var(--better-main) 50%, transparent);
}

.home-container {
  background: transparent !important;
}

.timetable-container,
.calendar,
.upcoming-assessment,
.upcoming-container,
.notices-container {
  background: linear-gradient(
      165deg,
      color-mix(in srgb, var(--arctic-panel) 90%, transparent),
      color-mix(in srgb, var(--background-secondary) 86%, transparent)
    ) !important;
  border: 1px solid var(--arctic-border) !important;
  border-radius: 14px !important;
  box-shadow: 0 14px 42px rgba(0, 0, 0, 0.4);
}

.timetable-container .home-subtitle,
.upcoming-container .home-subtitle,
.notices-container .home-subtitle,
.shortcut-container .home-subtitle,
#home-lesson-subtitle {
  color: var(--text-primary) !important;
}

.upcoming-filters,
.upcoming-checkbox-container,
.upcoming-checkmark {
  color: var(--text-primary) !important;
}

.upcoming-date-title,
.upcoming-date-title h5,
.upcoming-details h5,
.upcoming-details p,
.upcoming-assessment-title,
.upcoming-special-day {
  color: var(--text-primary) !important;
}

.notices-container input[type="date"] {
  color: var(--text-primary) !important;
  background: color-mix(in srgb, var(--background-primary) 94%, transparent) !important;
  border: 1px solid var(--arctic-border) !important;
}

.notices-container input[type="date"]::-webkit-calendar-picker-indicator {
  display: block !important;
  -webkit-appearance: auto !important;
  filter: invert(1);
  opacity: 0.85;
  cursor: pointer;
}

.notice-container,
.notice-unified-content,
.notice-content-title,
.notice-content-body,
.notice-preview,
.notice-staff {
  color: var(--text-primary) !important;
}

/* Panels that use CSS modules — extra presence */
[class*="BasicPanel__BasicPanel___"],
[class*="RootModule__root-module___"] [class*="Module__wrapper___"] {
  border-radius: 14px !important;
  border: 1px solid color-mix(in srgb, var(--better-main) 22%, var(--arctic-border)) !important;
  box-shadow: 0 14px 44px rgba(0, 0, 0, 0.38) !important;
}

[class*="MessageList__MessageList___"] {
  border-radius: 14px !important;
  box-shadow: 0 10px 36px rgba(0, 0, 0, 0.35) !important;
}

/* BetterSEQTA+ addedButton — light icons (avoid stroke+fill = thick/clipped look) */
.addedButton svg {
  color: #ffffff !important;
}

.addedButton svg circle,
.addedButton svg rect,
.addedButton svg polygon {
  fill: currentColor !important;
}

.addedButton svg path {
  fill: currentColor !important;
  stroke: none !important;
}

.addedButton svg path[fill="none"],
.addedButton svg path:not([fill]) {
  fill: none !important;
  stroke: currentColor !important;
}

.addedButton svg line,
.addedButton svg polyline {
  fill: none !important;
  stroke: currentColor !important;
}
/* Lexical / SEQTA modules — never force black text on dark theme */
html.dark [class*="Module__wrapper___"],
html.dark [class*="Module__module___"],
html.dark [class*="Module__content___"] {
  background: color-mix(in srgb, var(--background-secondary) 92%, transparent) !important;
  color: var(--text-primary) !important;
}

html.dark [class*="LexicalEditor__"] {
  color: var(--text-primary) !important;
}

html.dark [class*="LexicalEditor__"] .editor-paragraph,
html.dark [class*="LexicalEditor__"] [class*="editor-heading"],
html.dark [class*="LexicalEditor__"] [class*="editor-paragraph"],
html.dark [class*="LexicalEditor__"] span[data-lexical-text="true"],
html.dark [class*="LexicalEditor__"] p,
html.dark [class*="LexicalEditor__"] h1,
html.dark [class*="LexicalEditor__"] h2,
html.dark [class*="LexicalEditor__"] h3,
html.dark [class*="LexicalEditor__"] h4,
html.dark [class*="LexicalEditor__"] strong {
  color: var(--text-primary) !important;
}

html.dark [class*="TextModuleBody__"] {
  color: var(--text-primary) !important;
}
